import{_ as a,o as s,c as e,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"实战：复杂度反推设计","description":"","frontmatter":{},"headers":[],"relativePath":"dsa/algorithms/complexity/practice.md","filePath":"dsa/algorithms/complexity/practice.md","lastUpdated":1788475713000}'),o={name:"dsa/algorithms/complexity/practice.md"};function n(l,t,r,d,p,h){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="实战-复杂度反推设计" tabindex="-1">实战：复杂度反推设计 <a class="header-anchor" href="#实战-复杂度反推设计" aria-label="Permalink to &quot;实战：复杂度反推设计&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>给你一组<strong>真实约束</strong>——数据量、QPS、延迟、内存预算——你能不能反推出&quot;在这个工程里只能用哪种复杂度的算法，然后再筛掉哪些算法，最后只剩一两个候选&quot;。这是工程现场最高频的&quot;看一眼就知道用什么&quot;的反射能力。复杂度分析到这一步才真正进入工程实践。</p><h2 id="经验阈值表-单机、-1s-内可跑" tabindex="-1">经验阈值表（单机、~1s 内可跑） <a class="header-anchor" href="#经验阈值表-单机、-1s-内可跑" aria-label="Permalink to &quot;经验阈值表（单机、~1s 内可跑）&quot;">​</a></h2><p>把这张表刻在脑子里。<strong>看到 n，第一反应是这张表</strong>：</p><table tabindex="0"><thead><tr><th>n 量级</th><th>可接受复杂度上限</th><th>工程直觉</th></tr></thead><tbody><tr><td>≤ 10</td><td>任意（甚至 O(n!)）</td><td>全枚举、回溯都能跑</td></tr><tr><td>≤ 20</td><td>O(2ⁿ)</td><td>状压 DP 的典型规模</td></tr><tr><td>≤ 100</td><td>O(n³)</td><td>三重循环 / Floyd-Warshall</td></tr><tr><td>≤ 1000</td><td>O(n²)</td><td>嵌套循环、朴素图算法</td></tr><tr><td>≤ 10⁴</td><td>O(n²) 紧</td><td>别再上 n²，准备 n log n</td></tr><tr><td>≤ 10⁵</td><td>O(n log n)</td><td>排序+二分/堆/线段树回退</td></tr><tr><td>≤ 10⁶</td><td>O(n log n) 勉强，O(n) 稳</td><td>越接近 O(n) 越稳</td></tr><tr><td>≥ 10⁷</td><td>O(n) 上限</td><td>单机已接近物理极限</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>这张表的基础是 ~10⁸ ops/sec——现代 CPU 单核的真实工作速率（cache 友好 + 100% 利用率），不是 GHz 标称的 ~10⁹ cycle/sec。<strong>~10⁸ 是把&quot;内存墙 + 分支预测 + SIMD 利用率&quot;全算进去后的保守数</strong>.</p></div><h2 id="完整反推流程" tabindex="-1">完整反推流程 <a class="header-anchor" href="#完整反推流程" aria-label="Permalink to &quot;完整反推流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 拿到约束：n / QPS / 延迟 / 内存</span></span>
<span class="line"><span>2. 用阈值表推断 ≥ 必须的复杂度上限</span></span>
<span class="line"><span>3. 列出所有&quot;算法 + 数据结构&quot;组合覆盖该上限</span></span>
<span class="line"><span>4. 逐项筛：常数因子、cache 友好性、可并行性、编码复杂度</span></span>
<span class="line"><span>5. 给候选实现，跑 benchmark</span></span>
<span class="line"><span>6. 不达标 → 回到 3 + 加抽象（换 OS 策略、上 SIMD、上 GPU、上 FPGA）</span></span></code></pre></div><p>这是&quot;算法 → OS → 硬件&quot;的反推链。第 4 步开始往硬件层探，到第 6 步可能就跳到 GPU/FPGA 重新做抽象。</p><h2 id="案例-1-亿条日志中找-top-k-高频词" tabindex="-1">案例 1：亿条日志中找 Top K 高频词 <a class="header-anchor" href="#案例-1-亿条日志中找-top-k-高频词" aria-label="Permalink to &quot;案例 1：亿条日志中找 Top K 高频词&quot;">​</a></h2><p>约束：百亿条日志 × 200 字节 ≈ 2 TB；要求 1s 内出结果。</p><h3 id="粗扫" tabindex="-1">粗扫 <a class="header-anchor" href="#粗扫" aria-label="Permalink to &quot;粗扫&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2 TB / 单机 SSD 顺序读 3 GB/s = ~700 s  ⇒ 单机做不完</span></span>
<span class="line"><span>1 s ⇒ 总数据吞吐至少 2 TB/s ⇒ 必须 sharding</span></span></code></pre></div><h3 id="走分布式" tabindex="-1">走分布式 <a class="header-anchor" href="#走分布式" aria-label="Permalink to &quot;走分布式&quot;">​</a></h3><p>每台机器分到 N/M 份，每份做局部 Top K，再用 reduce phase 合并：</p><ul><li>单机局部：堆 + 哈希表 → 复杂度 O(N/M · log K).</li><li>reduce：合并 M 份小 Top K，再做一次 O(M · log K) 排序.</li></ul><p>工程注意：</p><ol><li><strong>堆 + 哈希表</strong> 而不是 sort：sort 会 O((N/M) log (N/M))，慢一截；</li><li>推荐用 <strong>Count-Min Sketch</strong> 一次 sweep 取近似 Top K，准确度可接受且 O(N/M)；</li><li>mapreduce 框架（Hadoop）默认走 sort，open 算法定制时要 override。</li></ol><p>到这里反推就跳出了&quot;选什么数据结构&quot;——已经跳到分布式架构（map/reduce）和应用模式（sketch 替代精确）。</p><h2 id="案例-2-实时字符串匹配、模式集上万" tabindex="-1">案例 2：实时字符串匹配、模式集上万 <a class="header-anchor" href="#案例-2-实时字符串匹配、模式集上万" aria-label="Permalink to &quot;案例 2：实时字符串匹配、模式集上万&quot;">​</a></h2><p>约束：n ≈ 10⁷ 流式文本、模式集 P ≈ 10⁴、每个模式 ≤ 30 字符、单机、~100 ms / MB.</p><h3 id="朴素怀疑-kmp-per-pattern" tabindex="-1">朴素怀疑 KMP per pattern <a class="header-anchor" href="#朴素怀疑-kmp-per-pattern" aria-label="Permalink to &quot;朴素怀疑 KMP per pattern&quot;">​</a></h3><p><code>O(P · n) = 10⁴ × 10⁷ = 10¹¹</code> ops ⇒ 不可能 100 ms 跑完.</p><h3 id="反推让-沿文本扫描一次-⇒-aho-corasick" tabindex="-1">反推让&quot;沿文本扫描一次&quot; ⇒ Aho-Corasick <a class="header-anchor" href="#反推让-沿文本扫描一次-⇒-aho-corasick" aria-label="Permalink to &quot;反推让&quot;沿文本扫描一次&quot; ⇒ Aho-Corasick&quot;">​</a></h3><p>复杂度 <code>O(n + Σ|P| + hits)</code>：建 Trie 失败链 ~O(Σ|P|) 一次性预编译，文本扫一次。</p><p>工程常量角度看：</p><ul><li>顺序扫文本，cache miss 极少；</li><li>Trie 节点 ~字节级别数组（256 槽），cache 容易闪；</li><li>Java/Go 等都能轻松跑出 1 GB/s 的 AC 扫描率.</li></ul><p><strong>结论</strong>：选 AC 不是品味，是<strong>反推决定的唯一答案</strong>.</p><h2 id="案例-3-105-qps-的-lru-缓存" tabindex="-1">案例 3：10⁵ QPS 的 LRU 缓存 <a class="header-anchor" href="#案例-3-105-qps-的-lru-缓存" aria-label="Permalink to &quot;案例 3：10⁵ QPS 的 LRU 缓存&quot;">​</a></h2><p>约束：单次操作 ≤ 10 μs；CPU 单核 ~3 GHz.</p><p>10 μs = 30_000 cycles，但每次 cache miss 就 ~200 cycle，10 次 cache miss 就用掉 2 μs. <strong>缓存结构的 ops 数必须压到 30-50 ops</strong>，这才是真正可行上限.</p><h3 id="候选" tabindex="-1">候选 <a class="header-anchor" href="#候选" aria-label="Permalink to &quot;候选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>复杂度</th><th>实际 ops</th><th>难点</th></tr></thead><tbody><tr><td>哈希 + 双链</td><td>O(1) 摊还</td><td>~50</td><td>内存碎片 + 分配</td></tr><tr><td>哈希 + 数组 + 世代</td><td>O(1)</td><td>~30 但 cap 小</td><td>适配小上限</td></tr><tr><td>Cuckoo hashing</td><td>O(1) 摊还</td><td>~30-100</td><td>rehash 失败处理</td></tr></tbody></table><h3 id="工程层的反推" tabindex="-1">工程层的反推 <a class="header-anchor" href="#工程层的反推" aria-label="Permalink to &quot;工程层的反推&quot;">​</a></h3><p>代码上看是 <code>map[k]*Node</code>，但真要做 10⁵ QPS 必须：</p><ol><li><strong>预分配内存池</strong>：避免 <code>runtime.malloc</code> 在每 op 里触发；</li><li><strong>sharded map</strong>：单 map 在高并发下中心化锁（Go runtime 的 hash growth 用全局锁），分 16-64 片即可；</li><li><strong>lock-free</strong>：考虑用 <code>sync.Map</code>（读多写少）或 <code>craq</code> / <code>lfds</code> 这类 lock-free map；</li><li><strong>不写 undo/redo 日志</strong>：内存里 LRU 单次操作不要 WAL，否则延迟穿 latency 上线。</li></ol><p>到这里，<strong>反推已经从&quot;算法选型&quot;跳到&quot;并发同步策略&quot;</strong>。</p><h2 id="案例-4-分布式严格递增序号" tabindex="-1">案例 4：分布式严格递增序号 <a class="header-anchor" href="#案例-4-分布式严格递增序号" aria-label="Permalink to &quot;案例 4：分布式严格递增序号&quot;">​</a></h2><p>约束：10⁶ req/s、全局严格递增、可用性要求 99.99%.</p><ul><li>用 Redis counter：O(1) 但单点瓶颈 ~10⁵/s，挂；</li><li>用 atomic single-machine：单机 10⁶/s OK，但全局不行；</li><li>用雪花算法（Snowflake）：<code>timestamp(41bit) | worker_id(10bit) | seq(12bit)</code>，每台机器 O(1) 生成、全局递增；</li><li>但雪花不保证<strong>严格连续</strong>，gap 在时钟碰撞或 worker restart 时会出现.</li></ul><p>这就是为什么 10⁶ req/s 真实场景都基本用<strong>雪花替代品</strong>——并接受小概率 gap。<strong>复杂度不是瓶颈，争用+同步才是</strong>。</p><h2 id="案例反推到硬件" tabindex="-1">案例反推到硬件 <a class="header-anchor" href="#案例反推到硬件" aria-label="Permalink to &quot;案例反推到硬件&quot;">​</a></h2><p>考虑一个&quot;每秒 10 GB 视频帧，把每帧 RGB→YUV420 并下采样&quot;的负载：</p><ul><li>朴素 C 实现循环：~5 GB/s, 还差一半；</li><li>改 SIMD (<code>AVX2-pmulhrsw + packuswb</code>)：~30 GB/s；</li><li>上 GPU (<code>nvjpeg</code>)：~5-10 TB/s；</li><li>上 FPGA (<code>ISP pipeline</code>)：可直接 streaming 一帧 ~16 ms 不爆 buffer.</li></ul><p>你会发现：每往硬件层走一层，<strong>抽象相同（RGB → YUV 的逻辑没变），但实现常数提高几个数量级</strong>。这是&quot;软件 → 硬件&quot;反推的真实路径：当你纯软件层的常数因子打不进 SLA时，下一步不是优化代码而是<strong>换硬件抽象层</strong>.</p><h2 id="反推陷阱清单" tabindex="-1">反推陷阱清单 <a class="header-anchor" href="#反推陷阱清单" aria-label="Permalink to &quot;反推陷阱清单&quot;">​</a></h2><ol><li><strong>隐藏 O(n²)</strong>：循环里隐藏了 string 拼接 <code>&quot;a&quot; + &quot;b&quot; + &quot;c&quot;</code>，每次拷贝全串 ⇒ O(n²). 换 <code>StringBuilder / bytes.Buffer / fmt.Fprintf</code>.</li><li><strong>map 迭代 &quot;看起来 O(1)&quot;</strong>：实际 O(n).</li><li><strong>哈希 rehash 尖刺</strong>：长尾敏感场景要 <code>reserve</code> 或换 incremental rehash.</li><li><strong>递归深度</strong>：Python 默认 1000；Go 1.18+ 默认 1GB 栈，但深度递归仍有 GC + stack copy 代价. 对超深递归改迭代版.</li><li><strong>τ-抖动 vs 平均延迟</strong>：摊还 O(1) 也救不了硬实时.</li></ol><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><ol><li>给 10 TB 文本找出 top-10 高频词，单机 SSD，1 小时预算。给方案。</li><li>你接到一个 10⁶ QPS 的 LRU 缓存需求，硬盘只能扛住 10³ QPS；反推架构（一致性/分区/降级）。</li><li>给一段简单的 Python 代码，找出它的复杂度并改造：<div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> process</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(items):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> []</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> items:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">not</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            result.append(x)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result</span></span></code></pre></div><ul><li>用 <code>set</code> 而不是 list 做&quot;重复检查&quot;: <code>O(n²) → O(n)</code>.</li><li>但如果&quot;items 含不可哈希对象&quot;必须保留 O(n²) —— 选型仍要看语义.</li></ul></li></ol><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ul><li>看到规模第一反应是阈值表；</li><li>算法复杂度只解决&quot;形状&quot;，工程真实约束推你进 OS/硬件层；</li><li>反推的尽头往往不是&quot;换个数据结构&quot;，而是<strong>换抽象层</strong>——SIMD/GPU/FPGA；</li><li>摊还 O(1) 在硬实时下不是 O(1)，平均 ≠ 最坏.</li></ul><p>下一章 → <a href="./../../structures/">基本数据结构</a></p>`,53)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
